{
  "findings": [
    {
      "ref": "R455",
      "area": "contact",
      "claim": "A parent reports no verify email button is visible, only a next button, preventing login.",
      "stance": "risk",
      "quote": "Where is the verify email button?\nI don’t see a verify email button all I see is next button and I can’t log in"
    },
    {
      "ref": "R462",
      "area": "age_gating",
      "claim": "A parent reports the app only serves up to 2nd grade, which no longer matches their 3rd grade child's level.",
      "stance": "risk",
      "quote": "My child is in 3rd grade and the app only has pre-k to 2nd grade. she loved it last year but now it’s not as fun anymore because it is not her level anymore."
    },
    {
      "ref": "R463",
      "area": "age_gating",
      "claim": "A parent reports the app cuts off learning for children above second grade and requests it go up to at least grade 5.",
      "stance": "risk",
      "quote": "I gave the review four stars solely for the reason that this fantastic app sadly cuts off learning for children above second grade. My daughter absolutely loves this app for learning through fun and games. She has been playing this app for years and sadly it cannot take her any further. I can’t seem to find anything like it for her educational level and it’s sad. PLEASE PLEASE PLEASE AT LEAST GO UP TO GRADE 5!"
    },
    {
      "ref": "R488",
      "area": "usability",
      "claim": "A parent reports the home button exits a lesson without confirmation, causing loss of progress and frustration for young children.",
      "stance": "mitigation",
      "quote": "Great app with lots of content across reading, writing, math, general knowledge. My one big complaint is that during each lesson there is a home icon button that exits out of the current lesson with no confirmation. You lose your progress and can’t immediately open the lesson back up (unless you find it in the library). Another random lesson opens. This happens so often with my young kids, and it’s so frustrating. Can you please add a confirmation dialog if the home button is pressed before the lesson is over?"
    },
    {
      "ref": "R476",
      "area": "content",
      "claim": "A parent reports the app lacks harder educational levels for older children.",
      "stance": "risk",
      "quote": "I need harder educational levels to learn more."
    },
    {
      "ref": "R472",
      "area": "content",
      "claim": "A parent reports the app is marketed for ages two through eight, but their ten-year-old found only super easy questions and felt it was not appropriate for third grade and up.",
      "stance": "risk",
      "quote": "So I was looking for math games for my ten year old and this popped up. I went though and it had super easy questions. I looked and it was ages two though eight. Not saying this is bad but third grade and up should not play."
    },
    {
      "ref": "R492",
      "area": "data",
      "claim": "A parent reports the touch option seems to be disabled, indicating possible functional issues with interaction.",
      "stance": "risk",
      "quote": "Touch option seems to be disabled"
    },
    {
      "ref": "R475",
      "area": "usability",
      "claim": "A parent reports every game opens with an error, preventing use.",
      "stance": "risk",
      "quote": "Every game we open gives an error and we can’t do anything."
    },
    {
      "ref": "R489",
      "area": "usability",
      "claim": "A parent reports the app crashes when switching between child accounts, preventing multiple children from using it.",
      "stance": "risk",
      "quote": "Only one of my kids can use the app, when we select the other child’s account the app crashes."
    },
    {
      "ref": "R497",
      "area": "content",
      "claim": "A parent reports the app has no ads and provides great learning while enjoying graphics, making it a safe and effective educational tool.",
      "stance": "neutral",
      "quote": "I’ve been monitoring my kids use on electronics- this one def hits the mark- great learning while enjoying the graphics. Glad I downloaded it!"
    },
    {
      "ref": "R498",
      "area": "money",
      "claim": "A parent reports the app has no in-app purchases, loot boxes, or pay-to-win elements, and is entirely free.",
      "stance": "mitigation",
      "quote": "LOVELY❤️❤️❤️❤️❤️ This game is great! It has helped my kids learn math easily and love seeing them come to me and show me how many stars they got on a lesson. I wanted my prior for them to learn math better and This game is extremely effective to them and exceptional for them to get on there iPads and play! It gives me so much joy when the get 105's on their math questions. This game is absolutely beautiful and amazing! Both of the boys have no problem when I ask them a math question and they get it right on the first try! Thank you so much for making this game for my two little boys❤️👍"
    },
    {
      "ref": "R450",
      "area": "money",
      "claim": "A user reports deleting the app after feeling it taught them things they already learned, indicating dissatisfaction with content relevance.",
      "stance": "risk",
      "quote": "I got the game when I was 6 years old and it was teaching me Things I Learned 😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡😡 And because of that, I deleted the game"
    },
    {
      "ref": "R490",
      "area": "usability",
      "claim": "A parent reports the app lacks language settings, making it difficult to access language options.",
      "stance": "risk",
      "quote": "Can’t find language settings boo"
    },
    {
      "ref": "R467",
      "area": "contact",
      "claim": "A user reports needing to use an email address like other learning games and requests a change to the login process.",
      "stance": "risk",
      "quote": "How to use your email address like all all the learning games I’ve been using so if you could please change it I would like you to"
    },
    {
      "ref": "R486",
      "area": "usability",
      "claim": "A parent reports the app caused their children to become so engaged that they missed supper, indicating high engagement but also potential overuse.",
      "stance": "neutral",
      "quote": "I called my kids for supper but nobody came! I went to chek on them and I saw them glued to this game and I was wondering what it was. The next thing I new my kids were coming home with all a’s on their tests and that’s when I truly new what this game was thankes to this game!"
    }
  ]
}
